function attackPower(s,profile={},includeDirect=true){const b=s.passives,weapon=profile.hand==='offhand'?s.off:s.main,kind=profile.kind||'physical',source=profile.source||'melee',isSpell=source==='spell',raw=profile.basePower??(isSpell?20+s.magia:(weapon?.power||10)*(1+s.forca/100));let bonus=(includeDirect?b.directDamage||0:0)+(kind==='physical'?b.physical||0:b.magicDamage||0);if(['fire','cold','lightning'].includes(kind))bonus+=(b.elemental||0)+(b[kind]||0);if(source==='melee')bonus+=b.melee||0;if(source==='projectile')bonus+=b.projectile||0;if(profile.area)bonus+=b.area||0;if(!isSpell&&weapon){bonus+=weapon.hands===2?b.twoHand||0:b.oneHand||0;if(s.dual)bonus+=b.dual||0;}return raw*factor(bonus)*(profile.multiplier||1);}
